CREATE TABLE IF NOT EXISTS public."promotional_video_replies" (
    "reply_id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "comment_id" bigint NOT NULL
        REFERENCES public."promotional_video_comments" ("comment_id") ON DELETE CASCADE,
    "user_id" integer NOT NULL REFERENCES public."users" ("user_id") ON DELETE CASCADE,
    "reply" text NOT NULL CHECK (length(btrim("reply")) BETWEEN 1 AND 1000),
    "created_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS "promotional_video_replies_comment_created_idx"
    ON public."promotional_video_replies" ("comment_id", "created_at", "reply_id");

ALTER TABLE public."promotional_video_replies" ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public."promotional_video_replies" FROM PUBLIC, anon, authenticated;
GRANT ALL ON TABLE public."promotional_video_replies" TO service_role;
GRANT USAGE, SELECT ON SEQUENCE public."promotional_video_replies_reply_id_seq" TO service_role;

CREATE OR REPLACE FUNCTION public.get_promotional_video_discussion()
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $function$
    SELECT jsonb_build_object(
        'video_url', (
            SELECT settings."video_url"
              FROM public."promotional_video_settings" AS settings
             WHERE settings."setting_id" = 1
        ),
        'likes_count', (
            SELECT count(*) FROM public."promotional_video_likes"
        ),
        'comments_count', (
            SELECT count(*) FROM public."promotional_video_comments"
        ),
        'liked_by_me', CASE
            WHEN auth.uid() IS NULL THEN false
            ELSE EXISTS (
                SELECT 1
                  FROM public."promotional_video_likes" AS video_like
                  JOIN public."users" AS account ON account."user_id" = video_like."user_id"
                 WHERE account."auth_user_id" = auth.uid()
                   AND account."is_active" = 1
            )
        END,
        'comments', COALESCE((
            SELECT jsonb_agg(
                jsonb_build_object(
                    'comment_id', visible_comment."comment_id",
                    'full_name', COALESCE(
                        NULLIF(btrim(visible_comment."full_name"), ''),
                        visible_comment."username",
                        'User'
                    ),
                    'comment', visible_comment."comment",
                    'created_at', visible_comment."created_at",
                    'is_mine', visible_comment."is_mine",
                    'replies_count', visible_comment."replies_count",
                    'replies', visible_comment."replies"
                )
                ORDER BY visible_comment."created_at" DESC, visible_comment."comment_id" DESC
            )
              FROM (
                SELECT root_comment."comment_id",
                       root_comment."full_name",
                       root_comment."username",
                       root_comment."comment",
                       root_comment."created_at",
                       root_comment."is_mine",
                       (SELECT count(*)
                          FROM public."promotional_video_replies" AS reply_count
                         WHERE reply_count."comment_id" = root_comment."comment_id"
                       ) AS "replies_count",
                       COALESCE((
                           SELECT jsonb_agg(
                               reply_item."reply_data"
                               ORDER BY reply_item."created_at", reply_item."reply_id"
                           )
                             FROM (
                                SELECT
                                    jsonb_build_object(
                                        'reply_id', video_reply."reply_id",
                                        'full_name', COALESCE(
                                            NULLIF(btrim(reply_author."full_name"), ''),
                                            reply_author."username",
                                            'User'
                                        ),
                                        'reply', video_reply."reply",
                                        'created_at', video_reply."created_at",
                                        'is_mine', auth.uid() IS NOT NULL
                                            AND reply_author."auth_user_id" = auth.uid()
                                            AND reply_author."is_active" = 1
                                    ) AS "reply_data",
                                    video_reply."created_at",
                                    video_reply."reply_id"
                                  FROM public."promotional_video_replies" AS video_reply
                                  JOIN public."users" AS reply_author
                                    ON reply_author."user_id" = video_reply."user_id"
                                 WHERE video_reply."comment_id" = root_comment."comment_id"
                                 ORDER BY video_reply."created_at" DESC, video_reply."reply_id" DESC
                                 LIMIT 100
                             ) AS reply_item
                       ), '[]'::jsonb) AS "replies"
                  FROM (
                    SELECT video_comment."comment_id",
                           comment_author."full_name",
                           comment_author."username",
                           video_comment."comment",
                           video_comment."created_at",
                           auth.uid() IS NOT NULL
                               AND comment_author."auth_user_id" = auth.uid()
                               AND comment_author."is_active" = 1 AS "is_mine",
                           row_number() OVER (
                               ORDER BY video_comment."created_at" DESC, video_comment."comment_id" DESC
                           ) AS "list_position"
                      FROM public."promotional_video_comments" AS video_comment
                      JOIN public."users" AS comment_author
                        ON comment_author."user_id" = video_comment."user_id"
                  ) AS root_comment
                 WHERE root_comment."list_position" <= 100 OR root_comment."is_mine"
              ) AS visible_comment
        ), '[]'::jsonb)
    );
$function$;

CREATE OR REPLACE FUNCTION public.add_promotional_video_reply(
    p_comment_id bigint,
    p_reply text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE
    app_user_id integer;
    comment_owner_id integer;
    reply_value text := btrim(COALESCE(p_reply, ''));
    new_reply_id bigint;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Sign in to reply to a comment.';
    END IF;

    app_user_id := public.current_app_user_id();
    IF app_user_id IS NULL THEN
        RAISE EXCEPTION 'An active account is required to reply.';
    END IF;
    IF p_comment_id IS NULL OR p_comment_id <= 0
       OR length(reply_value) NOT BETWEEN 1 AND 1000 THEN
        RAISE EXCEPTION 'Replies must be between 1 and 1,000 characters.';
    END IF;

    SELECT "user_id"
      INTO comment_owner_id
      FROM public."promotional_video_comments"
     WHERE "comment_id" = p_comment_id;
    IF comment_owner_id IS NULL THEN
        RAISE EXCEPTION 'Comment not found.';
    END IF;
    IF comment_owner_id = app_user_id THEN
        RAISE EXCEPTION 'You can reply only to another user''s comment.';
    END IF;

    INSERT INTO public."promotional_video_replies" ("comment_id", "user_id", "reply")
    VALUES (p_comment_id, app_user_id, reply_value)
    RETURNING "reply_id" INTO new_reply_id;

    RETURN jsonb_build_object('type', 'success', 'reply_id', new_reply_id);
END;
$function$;

REVOKE ALL ON FUNCTION public.add_promotional_video_reply(bigint, text)
    FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.add_promotional_video_reply(bigint, text)
    TO authenticated;
